package org.acme.discord.infrastructure.mappingtest;

import java.lang.reflect.Field;
import java.util.UUID;

/**
 * Test support for assigning identifiers normally generated by JPA.
 */
final class MapperTestSupport {

    private MapperTestSupport() {
    }

    static void setId(Object entity, UUID id) {
        try {
            Field field = entity.getClass().getDeclaredField("id");
            field.setAccessible(true);
            field.set(entity, id);
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Unable to assign test identifier", exception);
        }
    }
}
